def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    change_ratio = change / v1
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "starting_value_2016": v1,
            "ending_value_2017": v2,
            "absolute_change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
